'use client'

import { Hash, Menu, Users } from 'lucide-react'
import { Channel, Message, ReactionsMap, CustomEmojis } from '@/types'
import MessageList from './MessageList'
import MessageForm from './MessageForm'

type AvatarMap = Record<string, string>

interface Props {
  channel: Channel
  messages: Message[]
  onSendMessage: (content: string) => Promise<void>
  onMenuClick: () => void
  userName: string
  memberCount?: number
  hasMore?: boolean
  onLoadMore?: () => void
  reactionsMap?: ReactionsMap
  avatarMap?: AvatarMap
  customEmojis?: CustomEmojis
  onAddReaction?: (msg: Message, reaction: string) => void
  onEditMessage?: (msgId: string, newContent: string) => void
  onDeleteMessage?: (msgId: string) => void
}

export default function ChatArea({
  channel,
  messages,
  onSendMessage,
  onMenuClick,
  userName,
  memberCount,
  hasMore,
  onLoadMore,
  reactionsMap,
  avatarMap,
  customEmojis,
  onAddReaction,
  onEditMessage,
  onDeleteMessage,
}: Props) {
  return (
    <div className="flex flex-col h-full min-h-0 bg-white">
      {/* ヘッダー: モバイルはfixed固定、PCはstickyでレイアウト内に留まる */}
      <div className="fixed top-0 left-0 right-0 z-50 md:sticky md:left-auto md:right-auto md:z-10 flex items-center justify-between px-4 border-b border-gray-200 bg-white shadow-sm h-14 flex-shrink-0">
        <div className="flex items-center gap-3">
          {/* モバイル用メニューボタン: 常時表示 */}
          <button
            onClick={onMenuClick}
            className="md:hidden p-2 rounded-lg hover:bg-gray-100 active:bg-gray-200 transition-colors"
          >
            <Menu size={18} className="text-gray-600" />
          </button>

          <div className="flex items-center gap-2">
            <Hash size={18} className="text-gray-500" />
            <h1 className="font-bold text-gray-900 text-[15px]">{channel.name}</h1>
          </div>

          {channel.description && (
            <>
              <div className="w-px h-5 bg-gray-300 hidden sm:block" />
              <span className="text-sm text-gray-500 hidden sm:block truncate max-w-xs">
                {channel.description}
              </span>
            </>
          )}
        </div>

        {/* 右側: メンバー数など */}
        <div className="flex items-center gap-2 text-gray-500">
          {memberCount !== undefined && (
            <div className="flex items-center gap-1.5 text-sm">
              <Users size={15} />
              <span>{memberCount}</span>
            </div>
          )}
        </div>
      </div>

      {/* モバイルのfixedヘッダー分のスペーサー（PCでは非表示） */}
      <div className="h-14 flex-shrink-0 md:hidden" aria-hidden="true" />

      {/* メッセージ一覧 */}
      <MessageList
        messages={messages}
        currentUserName={userName}
        channelName={channel.name}
        hasMore={hasMore}
        onLoadMore={onLoadMore}
        reactionsMap={reactionsMap}
        avatarMap={avatarMap}
        customEmojis={customEmojis}
        onAddReaction={onAddReaction}
        onEditMessage={onEditMessage}
        onDeleteMessage={onDeleteMessage}
      />

      {/* 入力フォーム */}
      <div className="flex-shrink-0 border-t border-gray-100">
        <MessageForm
          onSubmit={onSendMessage}
          channelName={channel.name}
          disabled={!userName}
        />
      </div>
    </div>
  )
}
